		results[i] = ApplyResult{ID: it.ID, Created: true, Cursor: cursor}
	}
	// phase 2: apply
	if doc == nil {
		doc = &document{byID: map[string]int{}}
		s.docs[docID] = doc
	}
	for i, it := range items {
		if !results[i].Created {
